# Língua Portuguesa — L22 onda 5: reforço (interpretação, reescrita, coesão, orações, sintaxe, pontuação, concordância). Itens curtos; comentário objetivo (regra + pegadinha).
Q = []
TAILS=[" Essa seria a orientação predominante nas gramáticas normativas.",
 " Trata-se de entendimento corrente na norma-padrão.",
 " Tal solução decorreria, segundo esse entendimento, da estrutura da frase.",
 " Essa seria a leitura mais aceita pelos gramáticos."]
SHORT=[" Isso é consenso."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o uso padrão."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.95*len(C) and gap > 8: return E+SHORT[i%len(SHORT)]
    return E
FG={"tipo":"gramatica","ref":"norma-padrão (Bechara; Cegalla; Cunha e Cintra)","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag):
    ex={"fonte":FG,"risco":["doutrina_conhecimento"]}
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n=[0]
def S(ponto, atom, padE, dif, C, E, com, terro):
    _n[0]+=1
    P(ponto,[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"t{_n[0]:02d}")

PT_={**{i:"LP01" for i in range(1,7)},**{i:"LP02" for i in range(7,13)},13:"LP04",14:"LP04",15:"LP04",16:"LP06",17:"LP06",18:"LP06",19:"LP06",20:"LP07",21:"LP03",22:"LP03",23:"LP03",**{i:"LP05" for i in range(24,30)}}
def X(atom, padE, dif, C, E, com, terro):
    S(PT_[atom], atom, padE, dif, C, E, com, terro)
def J(atom, padE, dif, texto, C, E, com, terro):
    t="“"+texto+"” — "
    S(PT_[atom], atom, padE, dif, t+C, t+E, com, terro)

# ---- interpretação (24-29)
J(24,"generalizacao",3,"O órgão informou que as inscrições seriam reabertas caso o número de vagas não fosse preenchido.","Se as vagas forem preenchidas, não há previsão de reabertura das inscrições.","Mesmo que as vagas sejam preenchidas, as inscrições serão reabertas.","Reabertura depende de vagas sobrando.","ignora a condição")
J(24,"troca_efeito",3,"A auditoria identificou falhas em dois dos cinco contratos analisados.","Três dos contratos analisados não tiveram falhas identificadas pela auditoria.","A maioria dos contratos analisados apresentou falhas.","2 de 5 não é maioria.","erra a proporção")
J(24,"generalizacao",3,"O recurso foi admitido, mas seu mérito ainda não foi julgado.","O tribunal aceitou processar o recurso sem decidir se ele procede.","O tribunal negou provimento ao recurso.","Admitir ≠ prover.","confunde admissão e provimento")
J(24,"troca_efeito",2,"Desde 2020, o número de atendimentos presenciais caiu, enquanto o de atendimentos digitais triplicou.","Os atendimentos digitais aumentaram no período, e os presenciais diminuíram.","Os atendimentos presenciais e digitais aumentaram no período.","Enquanto = contraste.","ignora o contraste")
J(24,"generalizacao",3,"O prefeito vetou o trecho que previa o aumento da taxa, mas sancionou o restante da lei.","A lei foi sancionada em parte.","A lei foi integralmente vetada.","Veto parcial.","amplia o veto")
J(24,"troca_efeito",3,"Nenhum candidato foi eliminado na primeira fase, embora dois tenham obtido nota mínima.","Os candidatos que obtiveram nota mínima permaneceram no certame.","Os dois candidatos que obtiveram nota mínima foram eliminados.","Ninguém foi eliminado.","contradiz o texto")
J(25,"troca_efeito",3,"Mais do que punir o infrator, a multa pretende desestimular a repetição da conduta.","Para o texto, a função principal da multa é preventiva.","Para o texto, a finalidade principal da multa é punir o infrator.","'Mais do que punir' = prevenir.","inverte a prioridade")
J(25,"atribuicao_autor",2,"A reforma administrativa divide opiniões: para uns, moderniza o Estado; para outros, fragiliza o serviço público.","O texto apresenta duas avaliações opostas da reforma administrativa.","O texto defende que a reforma moderniza o Estado.","Texto expõe, não defende.","atribui tese ao autor")
J(25,"troca_efeito",2,"O sigilo é a exceção; a publicidade, a regra. Só a lei pode restringi-la, e nos limites da necessidade.","O texto afirma que a publicidade é a regra e o sigilo, a exceção.","O texto afirma que o sigilo é a regra e a publicidade, a exceção.","Regra = publicidade.","inverte regra e exceção")
J(25,"troca_efeito",3,"Não se discute a importância do concurso público; discute-se a forma de realizá-lo.","O objeto da controvérsia é a forma de realização do concurso, não a sua importância.","O objeto da controvérsia é a importância do concurso público.","Negação + contraste.","inverte o objeto da discussão")
J(25,"troca_efeito",3,"O texto legislativo deve ser claro, preciso e ordenado; do contrário, gera insegurança jurídica.","O texto relaciona a falta de clareza do texto legislativo à insegurança jurídica.","O texto afirma que a clareza do texto legislativo gera insegurança jurídica.","Do contrário = sem clareza.","inverte a relação")
J(26,"troca_efeito",3,"Com a nova regra, o servidor passa a ter de provar o que já era óbvio.","O trecho tem tom crítico em relação à nova regra.","O trecho tem tom elogioso em relação à nova regra.","'O que já era óbvio' = crítica.","lê crítica como elogio")
J(26,"conceito_correto",2,"A proposta nasceu morta: ninguém a defendeu no plenário.","A expressão “nasceu morta” tem sentido figurado: a proposta não teve apoio.","A expressão “nasceu morta” tem sentido literal.","Figurado.","lê figurado como literal")
J(26,"conceito_correto",3,"Os números falam por si.","Em “Os números falam por si” há personificação.","Em “Os números falam por si” há antítese.","Atribuir fala a coisa = personificação.","confunde figuras")
J(26,"troca_efeito",3,"Chamou a decisão de “histórica” e o fez sem corar, embora fosse a quarta idêntica do mês.","As aspas, no contexto, sugerem ironia em relação ao adjetivo “histórica”.","As aspas indicam citação literal de outro autor, sem ironia.","Aspas + contexto = ironia.","lê ironia como citação")
J(26,"troca_efeito",2,"O projeto caminha a passos de tartaruga na Comissão.","A expressão indica lentidão na tramitação do projeto.","A expressão indica rapidez na tramitação do projeto.","Tartaruga = lentidão.","inverte o sentido")
J(26,"conceito_correto",2,"A fila para o atendimento dava a volta no quarteirão.","A expressão enfatiza a extensão da fila, em recurso hiperbólico.","A expressão informa que a fila era curta.","Hipérbole = exagero.","inverte o sentido")
J(27,"atribuicao_autor",3,"Segundo o relatório, 80% dos órgãos cumpriram a meta; para o ministro, o resultado é “excelente”.","A avaliação “excelente” é atribuída ao ministro.","A avaliação “excelente” é do autor do texto.","Para o ministro = atribuição.","atribui ao autor")
J(27,"troca_efeito",2,"Provavelmente o prazo será prorrogado.","O advérbio “provavelmente” indica probabilidade, não certeza.","O advérbio “provavelmente” indica certeza quanto à prorrogação.","Provavelmente = probabilidade.","lê probabilidade como certeza")
J(27,"atribuicao_autor",3,"O deputado negou ter recebido o documento.","O texto registra a negativa do deputado, sem confirmá-la ou refutá-la.","O texto confirma que o deputado recebeu o documento.","Relato ≠ confirmação.","contradiz o relato")
J(27,"atribuicao_autor",3,"É lamentável que o prazo tenha sido perdido.","O trecho expressa juízo de valor do autor.","O trecho limita-se a relatar um fato, sem avaliação do autor.","Lamentável = juízo.","lê juízo como relato")
J(27,"generalizacao",3,"Os dados indicam, mas não comprovam, a eficácia do programa.","O texto reconhece indícios da eficácia do programa sem tê-la como comprovada.","O texto afirma que a eficácia do programa está comprovada.","Indicar ≠ comprovar.","transforma indício em prova")
J(28,"troca_efeito",2,"Como o relator se ausentou, a votação foi adiada.","A ausência do relator é apresentada como causa do adiamento da votação.","A ausência do relator é apresentada como consequência do adiamento da votação.","Como (inicial) = causa.","inverte causa e consequência")
J(28,"troca_efeito",3,"O texto é extenso; ainda assim, é de leitura fácil.","O trecho contrapõe a extensão do texto à facilidade de leitura.","O trecho apresenta a extensão do texto como causa da facilidade de leitura.","Ainda assim = contraste.","lê contraste como causa")
J(28,"troca_efeito",2,"Caso a emenda seja aprovada, o orçamento será revisto.","A revisão do orçamento depende da aprovação da emenda.","A aprovação da emenda depende da revisão do orçamento.","Condição → consequência.","inverte condição e consequência")
J(28,"troca_efeito",2,"O preço subiu e, por isso, a demanda caiu.","A queda da demanda é consequência da alta do preço.","A alta do preço é consequência da queda da demanda.","Por isso = consequência.","inverte causa e consequência")
J(28,"troca_efeito",3,"Conquanto o parecer seja técnico, tem forte carga política.","O trecho reconhece o caráter técnico do parecer, mas ressalva sua carga política.","O trecho nega o caráter técnico do parecer.","Conquanto = concessão.","lê concessão como negação")
J(29,"generalizacao",3,"Em regra, o prazo é de dez dias; a lei admite prorrogação em casos excepcionais.","O prazo de dez dias admite prorrogação em casos excepcionais.","O prazo de dez dias é improrrogável.","'Em regra' admite exceção.","apaga a exceção")
J(29,"generalizacao",3,"Muitos órgãos já adotaram o sistema, mas ainda há resistência em alguns.","O texto não afirma que todos os órgãos adotaram o sistema.","O texto afirma que todos os órgãos já adotaram o sistema.","Muitos ≠ todos.","generaliza")
J(29,"generalizacao",4,"A pesquisa ouviu 500 servidores e não pretende retratar o conjunto do funcionalismo.","Os resultados da pesquisa não devem ser generalizados para todo o funcionalismo.","Os resultados da pesquisa retratam o funcionalismo como um todo.","Amostra ≠ universo.","generaliza a amostra")
J(29,"troca_efeito",2,"O ministro disse que talvez renuncie.","O ministro não afirmou que renunciará.","O ministro afirmou que renunciará.","Talvez = incerteza.","lê dúvida como certeza")
J(29,"generalizacao",3,"Foram votadas três das dez propostas.","Sete propostas não foram votadas.","A maioria das propostas foi votada.","3 de 10.","erra a proporção")
# ---- reescrita (21-23)
X(21,"reescrita",2,"'O prazo foi prorrogado pelo relator' pode ser reescrito como 'O relator prorrogou o prazo', sem alteração de sentido.","'O prazo foi prorrogado pelo relator' pode ser reescrito como 'O prazo prorrogou o relator', sem alteração de sentido.","Passiva ↔ ativa.","inverte os papéis")
X(21,"reescrita",3,"'Vendem-se casas' é reescrita correta de 'Casas são vendidas'.","'Vende-se casas' é reescrita correta de 'Casas são vendidas'.","Se apassivador concorda.","verbo no singular")
X(21,"reescrita",3,"'Embora tenha estudado, não passou' pode ser reescrito como 'Apesar do estudo, não passou', sem mudança essencial de sentido.","'Embora tenha estudado, não passou' pode ser reescrito como 'Por causa do estudo, não passou', sem mudança essencial de sentido.","Embora = apesar de.","troca concessão por causa")
X(21,"reescrita",3,"'Os deputados aprovaram o projeto e saíram' pode ser reescrito como 'Após aprovarem o projeto, os deputados saíram', mantida a sequência temporal.","'Os deputados aprovaram o projeto e saíram' pode ser reescrito como 'Antes de aprovarem o projeto, os deputados saíram', mantida a sequência temporal.","Após = depois.","inverte a sequência")
X(21,"reescrita",4,"Em 'Ele só entregou o relatório ontem', o termo 'só' modifica o momento da entrega; em 'Só ele entregou o relatório', modifica o sujeito.","'Só' tem o mesmo escopo em 'Ele só entregou o relatório ontem' e em 'Só ele entregou o relatório'.","'Só' delimita o termo seguinte.","ignora o escopo")
X(21,"troca_efeito",4,"A frase 'Os candidatos que foram aprovados assinaram o termo' pode ser reduzida a 'Os candidatos aprovados assinaram o termo', sem alterar o sentido.","A frase 'Os candidatos que foram aprovados assinaram o termo' pode ser reescrita como 'Os candidatos, aprovados, assinaram o termo', sem alterar o sentido.","Vírgulas = explicativa.","vírgulas alteram o sentido")
X(22,"norma_culta",2,"Reescrever 'Os documentos chegaram' como 'Chegou os documentos' compromete a concordância.","A forma 'Chegou os documentos' atende à concordância verbal.","Verbo concorda com o sujeito.","singular com sujeito plural")
X(22,"norma_culta",2,"Em 'A decisão cabe ao Plenário', a troca por 'A decisão cabe o Plenário' compromete a regência.","Em 'A decisão cabe ao Plenário', a troca por 'A decisão cabe o Plenário' mantém a regência.","Caber a.","retira a preposição")
X(22,"norma_culta",3,"Trocar 'Aspiro a esse cargo' por 'Aspiro esse cargo' compromete a regência do verbo.","Trocar 'Aspiro a esse cargo' por 'Aspiro esse cargo' mantém a regência do verbo.","Aspirar (almejar) pede 'a'.","retira a preposição")
X(22,"norma_culta",3,"Trocar 'Prefiro ficar a sair' por 'Prefiro mais ficar do que sair' compromete a regência de 'preferir'.","Trocar 'Prefiro ficar a sair' por 'Prefiro mais ficar do que sair' mantém a regência de 'preferir'.","Preferir X a Y.","usa 'mais… do que'")
X(22,"norma_culta",2,"Reescrever 'Há dois anos que o processo tramita' como 'Fazem dois anos que o processo tramita' compromete a concordância.","Reescrever 'Há dois anos que o processo tramita' como 'Fazem dois anos que o processo tramita' mantém a concordância.","Fazer (tempo): impessoal.","pluraliza o impessoal")
X(22,"norma_culta",2,"Reescrever 'Houve falhas' como 'Houveram falhas' compromete a concordância.","Reescrever 'Houve falhas' como 'Houveram falhas' mantém a concordância.","Haver (existir): singular.","pluraliza o impessoal")
X(22,"troca_efeito",3,"Reescrever 'O ministro, que chegou cedo, assinou' como 'O ministro que chegou cedo assinou' pode alterar o sentido original.","Reescrever 'O ministro, que chegou cedo, assinou' como 'O ministro que chegou cedo assinou' não altera o sentido original.","Sem vírgulas = restritiva.","ignora a vírgula")
X(22,"norma_culta",2,"Reescrever 'Dirigiu-se à reitora' como 'Dirigiu-se a reitora' compromete a correção.","Reescrever 'Dirigiu-se à reitora' como 'Dirigiu-se a reitora' mantém a correção.","Dirigir-se a + a = à.","retira a crase")
X(23,"reescrita",2,"'Visto que' equivale a 'uma vez que' em 'Visto que o prazo acabou, encerrou-se a sessão'.","'Visto que' equivale a 'ainda que' em 'Visto que o prazo acabou, encerrou-se a sessão'.","Visto que = causa.","troca causa por concessão")
X(23,"reescrita",3,"'Sob pena de' introduz consequência negativa para o descumprimento, como em 'Entregue o relatório, sob pena de multa'.","'Sob pena de' introduz benefício pelo cumprimento, como em 'Entregue o relatório, sob pena de multa'.","Sob pena de = sanção.","inverte o sentido")
X(23,"reescrita",3,"'Em face de' pode indicar 'diante de', como em 'Em face das provas, o pedido foi acolhido'.","'Em face de' indica 'apesar de', como em 'Em face das provas, o pedido foi acolhido'.","Em face de = diante de.","troca por concessão")
X(23,"reescrita",3,"'Consoante' equivale a 'conforme': 'Consoante a lei, o prazo é de dez dias'.","'Consoante' equivale a 'embora': 'Consoante a lei, o prazo é de dez dias'.","Consoante = conforme.","troca por concessão")
X(23,"reescrita",3,"'À revelia de' significa sem o consentimento de.","'À revelia de' significa com a anuência de.","À revelia = sem consentimento.","inverte o sentido")
X(23,"reescrita",3,"'Cônscio' é sinônimo de ciente ou consciente.","'Cônscio' é sinônimo de ignorante.","Cônscio = ciente.","inverte o sentido")
# ---- coesão (13-15)
X(13,"troca_efeito",2,"Em 'O orçamento é limitado; assim, cada gasto deve ser justificado', 'assim' introduz conclusão.","Em 'O orçamento é limitado; assim, cada gasto deve ser justificado', 'assim' introduz oposição.","Assim = conclusão.","troca conclusão por oposição")
X(13,"troca_efeito",3,"Em 'Não votou nem se manifestou', a conjunção 'nem' tem valor aditivo (adição negativa).","Em 'Não votou nem se manifestou', a conjunção 'nem' tem valor adversativo.","Nem = adição negativa.","troca adição por oposição")
X(13,"troca_efeito",2,"Em 'Quer aprove, quer rejeite, o relator deve fundamentar', a correlação 'quer… quer' exprime alternância.","Em 'Quer aprove, quer rejeite, o relator deve fundamentar', a correlação 'quer… quer' exprime conclusão.","Quer… quer = alternância.","troca alternância por conclusão")
X(13,"troca_efeito",2,"Em 'O texto é longo, porém objetivo', 'porém' estabelece contraste.","Em 'O texto é longo, porém objetivo', 'porém' estabelece explicação.","Porém = contraste.","troca contraste por explicação")
X(14,"troca_efeito",2,"Em 'Desde que haja quórum, a sessão será aberta', 'desde que' introduz condição.","Em 'Desde que haja quórum, a sessão será aberta', 'desde que' introduz concessão.","Desde que = condição.","troca condição por concessão")
X(14,"troca_efeito",2,"Em 'Embora seja complexo, o tema é cobrado', a oração iniciada por 'embora' é concessiva.","Em 'Embora seja complexo, o tema é cobrado', a oração iniciada por 'embora' é causal.","Embora = concessão.","troca concessão por causa")
X(14,"troca_efeito",2,"Em 'Fale baixo para que ninguém ouça', a oração iniciada por 'para que' é final.","Em 'Fale baixo para que ninguém ouça', a oração iniciada por 'para que' é consecutiva.","Para que = finalidade.","troca finalidade por consequência")
X(14,"troca_efeito",2,"Em 'Segundo o regimento, o prazo é de cinco sessões', 'segundo' exprime conformidade.","Em 'Segundo o regimento, o prazo é de cinco sessões', 'segundo' exprime concessão.","Segundo = conformidade.","troca conformidade por concessão")
X(15,"atribuicao_autor",2,"Em 'A Câmara aprovou o projeto. Este segue ao Senado', 'este' retoma 'o projeto', o termo mais próximo.","Em 'A Câmara aprovou o projeto. Este segue ao Senado', 'este' retoma 'a Câmara'.","Este = o mais próximo.","retoma o referente errado")
X(15,"norma_culta",3,"Em 'Os servidores cujas férias foram suspensas serão compensados', 'cujas' concorda com 'férias'.","Em 'Os servidores cujas férias foram suspensas serão compensados', 'cujas' concorda com 'servidores'.","Cujo concorda com o possuído.","concorda com o possuidor")
X(15,"confusao_instituto",3,"Em 'Isto é certo: o prazo vence hoje', o pronome 'isto' antecipa o que será dito, configurando catáfora.","Em 'Isto é certo: o prazo vence hoje', o pronome 'isto' retoma o que já foi dito, configurando anáfora.","Antecipa = catáfora.","troca catáfora por anáfora")
X(15,"conceito_correto",3,"A repetição de uma palavra-chave ao longo do texto pode contribuir para a coesão lexical.","A repetição de uma palavra-chave ao longo do texto é incompatível com a coesão lexical.","Reiteração coesiva.","nega a coesão por repetição")
# ---- orações (16-19)
X(16,"confusao_instituto",3,"Em 'Estude, que o concurso se aproxima', a oração iniciada por 'que' é coordenada sindética explicativa.","Em 'Estude, que o concurso se aproxima', a oração iniciada por 'que' é coordenada sindética adversativa.","Que = explicativa.","troca explicativa por adversativa")
X(16,"confusao_instituto",3,"Em 'Não só trabalhou, mas também estudou', as orações estão em correlação aditiva.","Em 'Não só trabalhou, mas também estudou', as orações estão em correlação alternativa.","Não só… mas também = adição.","troca adição por alternância")
X(16,"confusao_instituto",2,"Em 'Era tarde; portanto, encerrou-se a sessão', a segunda oração é coordenada conclusiva.","Em 'Era tarde; portanto, encerrou-se a sessão', a segunda oração é coordenada adversativa.","Portanto = conclusiva.","troca conclusiva por adversativa")
X(17,"confusao_instituto",3,"Em 'Convém que todos compareçam', a oração iniciada por 'que' é subordinada substantiva subjetiva.","Em 'Convém que todos compareçam', a oração iniciada por 'que' é subordinada substantiva objetiva direta.","Convém (algo) = subjetiva.","troca subjetiva por objetiva")
X(17,"confusao_instituto",2,"Em 'Desejo que o relator seja ouvido', a oração subordinada é substantiva objetiva direta.","Em 'Desejo que o relator seja ouvido', a oração subordinada é substantiva subjetiva.","Desejo (algo) = objeto direto.","troca objetiva por subjetiva")
X(17,"confusao_instituto",4,"Em 'Estou certo de que o texto será votado', a oração subordinada é substantiva completiva nominal.","Em 'Estou certo de que o texto será votado', a oração subordinada é substantiva objetiva direta.","Completa o adjetivo 'certo'.","troca completiva por objetiva")
X(18,"confusao_instituto",3,"Em 'Os servidores, que eram concursados, foram mantidos', a oração adjetiva é explicativa.","Em 'Os servidores, que eram concursados, foram mantidos', a oração adjetiva é restritiva.","Entre vírgulas = explicativa.","troca explicativa por restritiva")
X(18,"conceito_correto",2,"A oração 'Chegando ao plenário, o relator discursou' é reduzida de gerúndio.","A oração 'Chegando ao plenário, o relator discursou' é reduzida de particípio.","-ando = gerúndio.","troca gerúndio por particípio")
X(18,"conceito_correto",3,"Em 'Mesmo estando cansado, concluiu o trabalho', a oração reduzida de gerúndio tem valor concessivo.","Em 'Mesmo estando cansado, concluiu o trabalho', a oração reduzida de gerúndio tem valor causal.","Mesmo… = concessão.","troca concessão por causa")
X(19,"reescrita",3,"'Conquanto o prazo seja curto, o relator concluiu' pode ser reescrito como 'Embora o prazo seja curto, o relator concluiu', sem alteração de sentido.","'Conquanto o prazo seja curto, o relator concluiu' pode ser reescrito como 'Porque o prazo é curto, o relator concluiu', sem alteração de sentido.","Conquanto = embora.","troca concessão por causa")
X(19,"reescrita",3,"'Para que haja transparência, os dados serão divulgados' pode ser reescrito como 'A fim de que haja transparência, os dados serão divulgados'.","'Para que haja transparência, os dados serão divulgados' pode ser reescrito como 'Embora haja transparência, os dados serão divulgados'.","Para que = a fim de que.","troca finalidade por concessão")
X(19,"reescrita",3,"'Quando o prazo terminar, a lista será divulgada' pode ser reescrito como 'Terminado o prazo, a lista será divulgada', sem alteração de sentido.","'Quando o prazo terminar, a lista será divulgada' pode ser reescrito como 'Embora termine o prazo, a lista será divulgada', sem alteração de sentido.","Tempo ↔ particípio.","troca tempo por concessão")
# ---- sintaxe (20)
X(20,"confusao_instituto",3,"Em 'Fazia dois anos que não chovia', o verbo 'fazer' é impessoal.","Em 'Fazia dois anos que não chovia', o sujeito de 'fazia' é 'dois anos'.","Fazer (tempo): sem sujeito.","vê sujeito em verbo impessoal")
X(20,"confusao_instituto",4,"Em 'Choveram críticas ao projeto', o verbo 'chover', em sentido figurado, admite sujeito.","Em 'Choveram críticas ao projeto', o verbo 'chover' permanece impessoal.","Chover figurado: pessoal.","mantém impessoal")
