X(2,"confusao_instituto",2,"Em 'Maria, minha colega, foi aprovada', as vírgulas isolam um aposto explicativo.","Em 'Maria, minha colega, foi aprovada', as vírgulas isolam um vocativo.","Aposto explica 'Maria'.","troca aposto por vocativo")
X(2,"confusao_instituto",3,"Em 'Os candidatos que não compareceram serão eliminados', a ausência de vírgulas indica oração restritiva.","Em 'Os candidatos que não compareceram serão eliminados', a ausência de vírgulas indica oração explicativa.","Sem vírgulas = restritiva.","troca restritiva por explicativa")
X(3,"norma_culta",2,"Em 'A proposta é, portanto, inconstitucional', 'portanto' vem isolado por vírgulas por estar intercalado.","Em 'A proposta é, portanto, inconstitucional', as vírgulas em torno de 'portanto' são indevidas.","Conclusiva intercalada: vírgulas.","nega a vírgula")
X(4,"norma_culta",3,"Em 'Quando o relator concluiu, o presidente abriu a discussão', a vírgula após a oração adverbial anteposta é adequada.","Em 'Quando o relator concluiu, o presidente abriu a discussão', a vírgula após a oração adverbial anteposta é indevida.","Adverbial anteposta: vírgula.","nega a vírgula")
X(4,"norma_culta",2,"Em 'Comprou livros, canetas e cadernos', não se usa vírgula antes do 'e' final da enumeração.","Em 'Comprou livros, canetas e cadernos', é obrigatória a vírgula antes do 'e' final da enumeração.","Antes do 'e': sem vírgula.","exige vírgula antes do 'e'")
X(6,"troca_efeito",3,"Em 'Vamos comer, crianças', a vírgula marca o vocativo; sem ela, 'comer crianças' alteraria o sentido.","Em 'Vamos comer, crianças', a retirada da vírgula não alteraria o sentido da frase.","Vírgula muda o sentido.","ignora o efeito da vírgula")
