X(7,"norma_culta",2,"Em 'O diretor e o chefe de gabinete foram à reunião', o verbo concorda com o sujeito composto.","Em 'O diretor e o chefe de gabinete foram à reunião', o verbo deveria ficar no singular.","Composto → plural.","singular com sujeito composto")
X(7,"norma_culta",3,"Em 'Eu e você votamos a favor', o verbo vai para a primeira pessoa do plural.","Em 'Eu e você votamos a favor', o verbo deveria ir para a segunda pessoa do plural.","Eu + você = nós.","pessoa errada")
X(8,"norma_culta",2,"O verbo 'fazer', indicando tempo decorrido, é impessoal: 'Faz dois anos que ele saiu'.","O verbo 'fazer', indicando tempo decorrido, concorda com o complemento: 'Fazem dois anos que ele saiu'.","Fazer (tempo): singular.","pluraliza o impessoal")
X(9,"norma_culta",3,"Em 'A maioria dos servidores aprovou a medida', o verbo no singular é adequado.","Em 'A maioria dos servidores aprovou a medida', o verbo no singular é inadequado.","Coletivo: singular.","nega o singular")
X(9,"norma_culta",3,"Em 'Fui eu que fiz o parecer', o verbo da oração relativa concorda com o pronome 'eu'.","Em 'Fui eu que fez o parecer', o verbo da oração relativa concorda com o pronome 'eu', como exige a norma-padrão.","Eu que fiz.","concorda com 'que'")
X(10,"norma_culta",2,"Em 'É uma hora', o verbo fica no singular; em 'São duas horas', fica no plural.","A forma 'É duas horas' atende à norma-padrão.","Verbo concorda com a hora.","singular com plural")
